from itertools import combinations

def is_triangle_free(edges, n=9):
    adj = [[False]*n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = True
        adj[v][u] = True
    for i in range(n):
        for j in range(i+1, n):
            if adj[i][j]:
                for k in range(j+1, n):
                    if adj[i][k] and adj[j][k]:
                        return False
    return True

def creates_triangle(edges, new_edge, n=9):
    adj = [[False]*n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = True
        adj[v][u] = True
    u, v = new_edge
    # Check if adding (u,v) creates a triangle
    for w in range(n):
        if w != u and w != v:
            if adj[u][w] and adj[v][w]:
                return True
    return False

def is_maximal_triangle_free(edges, n=9):
    if not is_triangle_free(edges, n):
        return False
    edge_set = set(edges)
    for u in range(n):
        for v in range(u+1, n):
            if (u,v) not in edge_set:
                if not creates_triangle(edges, (u,v), n):
                    return False  # Can add edge without triangle => not maximal
    return True

