def turan_3_partite(partition, n=9):
    edges = []
    for i, part_i in enumerate(partition):
        for j, part_j in enumerate(partition):
            if i < j:
                for u in part_i:
                    for v in part_j:
                        u2, v2 = min(u,v), max(u,v)
                        edges.append((u2, v2))
    return edges

